// Differential test: ~7000 random cases generated by the UPSTREAM Python (tools/gen_fuzz_vectors.py)
// must give identical results in the JS port.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { crc16, addDelimiters, removeDelimiters, fromHex, toHex } from '../src/protocol.js';
import { encryptPacket, decryptPacket, keyFromQR } from '../src/crypto.js';
import * as P from '../src/packets.js';

const F = JSON.parse(readFileSync(new URL('./fuzz.json', import.meta.url)));

test('fuzz: encryption and decryption identical to upstream', () => {
  for (const r of F.crypto) {
    const key = fromHex(r.key);
    assert.equal(toHex(encryptPacket(fromHex(r.spp), key, fromHex(r.iv))), r.packet);
    for (const c of r.decrypt) {
      const k = c.key ? fromHex(c.key) : key;
      const got = decryptPacket(fromHex(c.packet), k);
      assert.equal(got === null ? null : toHex(got), c.result, `decrypt case ${c.case}`);
    }
  }
});

test('fuzz: crc16 and byte stuffing identical', () => {
  for (const r of F.crc) assert.equal(crc16(fromHex(r.data)), r.crc);
  for (const r of F.stuffing) {
    assert.equal(toHex(addDelimiters(fromHex(r.raw))), r.stuffed);
    assert.equal(toHex(removeDelimiters(fromHex(r.stuffed))), r.unstuffed);
  }
});

test('fuzz: QR -> key identical', () => { for (const r of F.qr) assert.equal(toHex(keyFromQR(r.qr)), r.key); });

test('fuzz: packet builders identical', () => {
  for (const r of F.builders) {
    const b = new P.PacketBuilder(1, r.start);
    const a = r.args;
    const p = {
      wsm: () => b.writeSystemMode(a[0]), assist: () => b.writeAssistLevel(a[0]), mode: () => b.writeDriveMode(a[0]),
      profile: () => b.writeDriveProfile(a[0]), speed: () => b.writeRemoteSpeed(a[0]), readparams: () => b.readProfileParams(a[0]),
      params: () => b.writeProfileParams(a[0], { maxTorque: a[1], maxSpeedRaw: a[2], pFactor: a[3], speedBias: a[4], speedFactor: a[5], rotationThreshold: a[6], slopeInc: a[7], slopeDec: a[8] }),
    }[r.kind]();
    assert.equal(toHex(p), r.packet, r.kind);
  }
});

const near = (a, b) => Math.abs(a - b) < 1e-9 * Math.max(1, Math.abs(b));
const parsers = {
  soc: (u, j) => assert.equal(j, u),
  assist: (u, j) => assert.equal(j, u.value),
  profile: (u, j) => assert.equal(j, u.value),
  driveMode: (u, j) => { assert.equal(j.raw, u.value); assert.equal(j.autoHold, u.auto_hold); assert.equal(j.cruise, u.cruise); assert.equal(j.remote, u.remote); },
  params: (u, j) => {
    assert.equal(j.maxTorque, u.max_torque); assert.equal(j.maxSpeedRaw, u.max_speed_raw); assert.ok(near(j.maxSpeedKmh, u.max_speed));
    assert.equal(j.pFactor, u.p_factor); assert.equal(j.speedBias, u.speed_bias); assert.equal(j.speedFactor, u.speed_factor);
    assert.equal(j.rotationThreshold, u.rotation_threshold); assert.equal(j.slopeInc, u.slope_inc); assert.equal(j.slopeDec, u.slope_dec);
  },
  cruise: (u, j) => assert.ok(near(j.distanceKm, u.distance_km)),
  sw: (u, j) => { assert.equal(j.text, u.version_str); assert.equal(j.major, u.major); assert.equal(j.minor, u.minor); assert.equal(j.patch, u.patch); },
  duo: (u, j) => {
    assert.equal(j.mountingSide, u.mounting_side); assert.equal(j.speedSensibility, u.speed_sensibility); assert.equal(j.steeringDynamic, u.steering_dynamic);
    assert.equal(j.mounting === 'Unknown', u.mounting_name.startsWith('Unknown'));
    if (!u.mounting_name.startsWith('Unknown')) assert.equal(j.mounting, u.mounting_name);
  },
};
const jsParse = { soc: P.parseSOC, assist: P.parseAssistLevel, profile: P.parseDriveProfile, driveMode: P.parseDriveMode,
  params: P.parseProfileParams, cruise: P.parseCruiseValues, sw: P.parseSWVersion, duo: P.parseDuoDriveParams };

test('fuzz: response parsers identical (incl. null for short/invalid payloads)', () => {
  let n = 0;
  for (const r of F.parsers) {
    if (r.fn === 'header') {
      const j = P.parseHeader(fromHex(r.payload)), u = r.result;
      if (u === null) { assert.equal(j, null); continue; }
      assert.equal(j.protocolId, u.protocol_id); assert.equal(j.telegramId, u.telegram_id); assert.equal(j.source, u.source_id);
      assert.equal(j.dest, u.dest_id); assert.equal(j.service, u.service_id); assert.equal(j.param, u.param_id); assert.equal(toHex(j.payload), u.payload);
    } else {
      const j = jsParse[r.fn](fromHex(r.payload));
      if (r.result === null) assert.equal(j, null, `${r.fn} ${r.payload}`); else { assert.notEqual(j, null, `${r.fn} ${r.payload}`); parsers[r.fn](r.result, j); }
    }
    n++;
  }
  assert.ok(n > 5000);
});
